import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = () => {
  const [messages, setMessages] = useState([]);
  const [isLive, setIsLive] = useState(false);
  const [caption, setCaption] = useState("Click the Mic to Start");
  const [inputValue, setInputValue] = useState('');
  const [step, setStep] = useState('idle'); // idle -> language -> service -> booking/checkin
  const [selectedLang, setSelectedLang] = useState('en-IN');
  const scrollRef = useRef(null);

  // --- SERVICE IMAGE ASSETS ---
  const services = [
    { name: "Booking", img: "https://img.icons8.com/fluency/48/airplane-take-off.png" },
    { name: "Status", img: "https://img.icons8.com/fluency/48/info.png" },
    { name: "Check-in", img: "https://img.icons8.com/fluency/48/boarding-pass.png" },
    { name: "Baggage", img: "https://img.icons8.com/fluency/48/luggage.png" },
    { name: "Refund", img: "https://img.icons8.com/fluency/48/refund.png" },
    { name: "Lounge", img: "https://img.icons8.com/fluency/48/lounge.png" },
    { name: "Assistance", img: "https://img.icons8.com/fluency/48/customer-support.png" },
    { name: "Loyalty", img: "https://img.icons8.com/fluency/48/star.png" },
    { name: "Agent", img: "https://img.icons8.com/fluency/48/call-center-worker.png" },
    { name: "Info", img: "https://img.icons8.com/fluency/48/help.png" }
  ];

  const speak = (text, lang = 'en-IN', callback) => {
    const msg = new SpeechSynthesisUtterance(text);
    msg.lang = lang;
    msg.onstart = () => setCaption(text);
    msg.onend = () => callback && callback();
    window.speechSynthesis.speak(msg);
  };

  // --- STOPS ALL SPEECH IMMEDIATELY ---
  const stopAllSpeech = () => {
    window.speechSynthesis.cancel();
  };

  const startLanguageSelection = (index = 0) => {
    const langs = [
      { t: "For English, Press 1", l: "en-GB", v: "1" },
      { t: "తెలుగు కోసం, రెండు నొక్కండి", l: "te-IN", v: "2" },
      { t: "हिंदी के लिए, तीन दबाएं", l: "hi-IN", v: "3" },
      { t: "Malayalam, 4", l: "ml-IN", v: "4" },
      { t: "Tamil, 5", l: "ta-IN", v: "5" },
      { t: "Kannada, 6", l: "kn-IN", v: "6" },
      { t: "Bengali, 7", l: "bn-IN", v: "7" },
      { t: "Marathi, 8", l: "mr-IN", v: "8" },
      { t: "Gujarati, 9", l: "gu-IN", v: "9" },
      { t: "Punjabi, 10", l: "pa-IN", v: "10" }
    ];

    if (step !== 'language' || index >= langs.length) return;

    speak(langs[index].t, langs[index].l, () => {
      // Small delay before next language to allow user to interrupt
      setTimeout(() => startLanguageSelection(index + 1), 500);
    });
  };

  const handleInteraction = (val) => {
    const input = val.toLowerCase();
    addMessage("You", val);
    stopAllSpeech(); // KILL the language dictation loop immediately

    if (step === 'language') {
      if (input.includes("1") || input.includes("english")) {
        setSelectedLang('en-GB');
        setStep('service');
        speak("English Selected. Please choose a service.", "en-GB");
      } else if (input.includes("2") || input.includes("తెలుగు") || input.includes("telugu")) {
        setSelectedLang('te-IN');
        setStep('service');
        speak("తెలుగు ఎంపిక చేయబడింది. దయచేసి ఒక సేవను ఎంచుకోండి.", "te-IN");
      }
      // Add logic for other languages here...
    } 

    else if (step === 'service') {
      if (input.includes("1") || input.includes("booking")) {
        setStep('booking');
        speak("Where is your destination?", selectedLang);
      } else if (input.includes("3") || input.includes("check-in")) {
        setStep('checkin');
        speak("Please provide your PNR for check-in.", selectedLang);
      }
    }

    else if (step === 'booking') {
      const pnr = "AP" + Math.floor(Math.random() * 900000 + 100000);
      localStorage.setItem("latestPNR", pnr); // Integrated with Main UI
      speak(`Confirmed! Your PNR is ${pnr}. Gate T3-A12.`, selectedLang);
      addMessage("Voice Web", `✅ Booked to ${val}! PNR: ${pnr} | Gate: T3-A12 | Weather: 26°C`);
      setStep('done');
    }
    setInputValue('');
  };

  const addMessage = (sender, text) => {
    setMessages(prev => [...prev, { sender, text, time: new Date().toLocaleTimeString() }]);
  };

  return (
    <div style={{background: '#f1f5f9', height: '100vh', display: 'flex', flexDirection: 'column', fontFamily: 'Inter, sans-serif'}}>

      {/* HEADER - LOCKED TO UI SPEC */}
      <div style={{background: 'white', padding: '12px 40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #e2e8f0'}}>
        <div style={{display: 'flex', alignItems: 'center', gap: '12px'}}>
           <div style={{background: '#2563eb', color: 'white', padding: '8px', borderRadius: '10px'}}>✈️</div>
           <b style={{fontSize: '15px'}}>SKY-SYNC <span style={{fontSize: '9px', color: '#64748b', display: 'block'}}>VOICE WEB INTERFACE</span></b>
        </div>
        <div style={{display: 'flex', background: '#f1f5f9', padding: '4px', borderRadius: '25px'}}>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: 'transparent', fontSize: '13px'}}>Voice Call</button>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: '#2563eb', color: 'white', fontSize: '13px'}}>Voice Web</button>
        </div>
        <div style={{display: 'flex', alignItems: 'center', gap: '20px'}}>
           <span style={{cursor: 'pointer'}}>🔔</span><span style={{cursor: 'pointer'}}>❓</span>
           <div style={{width: '35px', height: '35px', borderRadius: '50%', background: '#cbd5e1', border: '2px solid white'}}></div>
        </div>
      </div>

      <div style={{display: 'grid', gridTemplateColumns: '260px 1fr 280px', gap: '20px', padding: '20px', flex: 1, overflow: 'hidden'}}>

        {/* LEFT: FLIGHT SERVICES (With Icons) */}
        <div style={{background: 'white', borderRadius: '24px', padding: '20px', boxShadow: '0 4px 10px rgba(0,0,0,0.02)'}}>
          <h4 style={{fontSize: '14px', marginBottom: '20px', color: '#1e293b'}}>Flight Services</h4>
          {services.map((s, i) => (
            <div key={i} style={{display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', marginBottom: '6px', borderRadius: '12px', background: step === 'service' ? '#eff6ff' : 'transparent'}}>
               <img src={s.img} alt={s.name} style={{width: '22px'}} />
               <span style={{fontSize: '12px', color: '#475569'}}>{i+1}. {s.name}</span>
            </div>
          ))}
        </div>

        {/* MIDDLE: SPLIT LAYOUT */}
        <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
           {/* Mic Area */}
           <div style={{background: 'white', borderRadius: '24px', padding: '30px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
              <p style={{fontSize: '12px', color: '#64748b', textAlign: 'center', height: '40px'}}>{caption}</p>
              <div onClick={() => { setStep('language'); startLanguageSelection(); setIsLive(true); }} style={{width: '180px', height: '180px', borderRadius: '50%', background: 'radial-gradient(circle, #2563eb 0%, #1e3a8a 100%)', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer'}} className={isLive ? 'pulse-mic' : ''}>
                 <span style={{fontSize: '50px'}}>🎙️</span>
              </div>
              <p style={{marginTop: '20px', color: '#2563eb', fontSize: '13px', fontWeight: '600'}}>● {isLive ? 'SYSTEM ACTIVE' : 'INITIALIZE AI'}</p>
           </div>

           {/* Transcript Area */}
           <div style={{background: 'white', borderRadius: '24px', padding: '20px', display: 'flex', flexDirection: 'column', overflow: 'hidden'}}>
              <b style={{fontSize: '13px', marginBottom: '15px', color: '#1e293b'}}>Live Transcript / Captions</b>
              <div style={{flex: 1, overflowY: 'auto'}} ref={scrollRef}>
                {messages.map((m, i) => (
                  <div key={i} style={{marginBottom: '10px', background: m.sender === 'You' ? '#eff6ff' : '#f8fafc', padding: '12px', borderRadius: '15px'}}>
                    <div style={{fontSize: '9px', color: '#2563eb', fontWeight: 'bold'}}>{m.sender} ({m.time})</div>
                    <div style={{fontSize: '12px', color: '#334155'}}>{m.text}</div>
                  </div>
                ))}
              </div>
           </div>
        </div>

        {/* RIGHT: QUICK SUGGESTIONS (With Icons) */}
        <div style={{background: 'white', borderRadius: '24px', padding: '20px'}}>
           <h4 style={{fontSize: '14px', marginBottom: '20px', color: '#1e293b'}}>Quick Help</h4>
           {[
             {t: 'Track Booking', i: 'https://img.icons8.com/fluency/48/radar.png'},
             {t: 'Weather Updates', i: 'https://img.icons8.com/fluency/48/partly-cloudy-day.png'},
             {t: 'Baggage Help', i: 'https://img.icons8.com/fluency/48/luggage.png'}
           ].map(q => (
             <div key={q.t} style={{display: 'flex', alignItems: 'center', gap: '10px', padding: '12px', border: '1px solid #f1f5f9', borderRadius: '12px', marginBottom: '10px', fontSize: '12px'}}>
               <img src={q.i} alt="icon" style={{width: '20px'}} /> {q.t}
             </div>
           ))}
        </div>
      </div>

      {/* BOTTOM INPUT */}
      <div style={{background: 'white', padding: '15px 40px', borderTop: '1px solid #e2e8f0', display: 'flex', gap: '15px'}}>
        <input 
          type="text" 
          placeholder="Type or speak selection..." 
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleInteraction(inputValue)}
          style={{flex: 1, padding: '12px 25px', borderRadius: '30px', border: '1px solid #e2e8f0', background: '#f8fafc', outline: 'none', fontSize: '13px'}} 
        />
        <button onClick={() => handleInteraction(inputValue)} style={{background: '#2563eb', color: 'white', border: 'none', padding: '0 30px', borderRadius: '30px', cursor: 'pointer', fontSize: '13px'}}>Send</button>
      </div>

      <style>{`
        .pulse-mic { animation: ripple 1.8s infinite; }
        @keyframes ripple {
          0% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.4); }
          70% { box-shadow: 0 0 0 30px rgba(37, 99, 235, 0); }
          100% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0); }
        }
      `}</style>
    </div>
  );
};

export default VoiceWeb;
